window.STORY_CHAPTERS["c89e69c4dfb44fba4"]={"id":"c89e69c4dfb44fba4","lines":[{"uid":"talk.vc.home_wait_edith_25#originalText","id":"talk.vc.home_wait_edith_25","speaker":{"cn":"伊迪丝","en":"Eydis"},"text":{"cn":"开始下雪了呢。希望暗之子民别趁这时候来捣乱。","en":"It's started to snow. I only hope Dark agents don't use it as cover to invade."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_egome_1#originalText","id":"talk.vc.home_wait_egome_1","speaker":{"cn":"伊格姆","en":"Egome","ja":"イゴーム"},"text":{"cn":"如果学生是你，我是可以教教萨卡莱特流。","en":"I wouldn't mind making a special case and teaching you Zakkarite style.","ja":"お前にだったらザッカライト流を教えてやってもいいぜ?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_egome_2#originalText","id":"talk.vc.home_wait_egome_2","speaker":{"cn":"伊格姆","en":"Egome","ja":"イゴーム"},"text":{"cn":"总有一天，我会挖出你「连续技」的秘密。","en":"Some day, I will unmask the secret behind your so-called \"combo-attacks.\"","ja":"お前の「連続技」その秘密はいつか暴いてやるからな"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_egome_3#originalText","id":"talk.vc.home_wait_egome_3","speaker":{"cn":"伊格姆","en":"Egome","ja":"イゴーム"},"text":{"cn":"有我当你的伙伴，很可靠吧？","en":"Don't you feel much safer having me as an ally?","ja":"俺が仲間にいると心強いだろ?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_egome_4#originalText","id":"talk.vc.home_wait_egome_4","speaker":{"cn":"伊格姆","en":"Egome","ja":"イゴーム"},"text":{"cn":"为求胜利不择手段，那就是强。","en":"I will do what it takes to win. That's what it means to be strong.","ja":"勝つためなら手段は選ばないそれが強いってことだ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_egome_9#originalText","id":"talk.vc.home_wait_egome_9","speaker":{"cn":"伊格姆","en":"Egome","ja":"イゴーム"},"text":{"cn":"都有我陪着了，怎么看你还一脸无聊样啊。","en":"You're looking awfully bored, especially considering you're in my company.","ja":"この俺と一緒にいるのにずいぶんつまらなそうじゃないか"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_egome_10#originalText","id":"talk.vc.home_wait_egome_10","speaker":{"cn":"伊格姆","en":"Egome"},"text":{"cn":"哎呀，你找伊格姆大人我有什么事呢？","en":"Whoa, there. Do you have business with me?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eiji_1#originalText","id":"talk.vc.home_wait_eiji_1","speaker":{"cn":"瑛二","en":"Eiji","ja":"エイジ"},"text":{"cn":"这个世界……跟现实没什么差别，这真的是VR吗？","en":"This world... Isn't any different from reality. Am I really in a VR?","ja":"この世界……現実となんら変わらない本当にVRなのか?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eiji_2#originalText","id":"talk.vc.home_wait_eiji_2","speaker":{"cn":"瑛二","en":"Eiji","ja":"エイジ"},"text":{"cn":"我……一定会保护好你。我已经跟过去软弱的我不一样了。","en":"I... I will absolutely protect you. I'm different than when I was weak.","ja":"僕は……絶対に君を守ってみせる弱かったあの頃とは違うんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eiji_3#originalText","id":"talk.vc.home_wait_eiji_3","speaker":{"cn":"瑛二","en":"Eiji","ja":"エイジ"},"text":{"cn":"如果是你的歌声，我想一定可以迷住这个世界的居民。","en":"Your voice will absolutely charm the people of this world.","ja":"君の歌なら、きっとこの世界の住人だって魅了できるはずさ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eiji_4#originalText","id":"talk.vc.home_wait_eiji_4","speaker":{"cn":"瑛二","en":"Eiji","ja":"エイジ"},"text":{"cn":"始终AR的感觉还是有点不一样呀。要快点习惯这边的动作才行。","en":"The sensations in the AR world truly are something. I need to hurry up and get used to these movements.","ja":"ARとは、やはり感覚が違うな早くこちらの動きに慣れなければ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eiji_9#originalText","id":"talk.vc.home_wait_eiji_9","speaker":{"cn":"瑛二","en":"Eiji","ja":"エイジ"},"text":{"cn":"……你对这世界真是兴趣昂然。","en":"...Such an endless interest in this world. It looks like I don't catch your attention anymore.","ja":"……この世界に興味津々だなもう僕なんか目に入っていないみたいだ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eldrie_1#originalText","id":"talk.vc.home_wait_eldrie_1","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"我得到了西帝国产的好酒，要不要一起喝呢？","en":"A fine wine from the West just arrived. Would you like to try some with me?","ja":"西帝国産のいいワインが入りましたご一緒にいかがですか?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eldrie_2#originalText","id":"talk.vc.home_wait_eldrie_2","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"为什么我会挂念那样的小孩子……老实说我自己也不明白。","en":"Why are you so preoccupied with that child? I honestly don't understand.","ja":"なぜあのような子どもを気にかけるのか……正直わかりかねます"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eldrie_3#originalText","id":"talk.vc.home_wait_eldrie_3","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"我可以跟您过两招吗？","en":"May we have a practice duel?","ja":"一手、お手合わせをお願いできますか?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eldrie_4#originalText","id":"talk.vc.home_wait_eldrie_4","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"我去看看泷刳。照顾龙也是集成骑士的责任。","en":"I'm going to go check on my dragon. Caring for one's dragon is a very important part of an Integrity Knight's duties.","ja":"滝刳の様子を見てきます竜の世話も、整合騎士の務めですからな"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eldrie_9#originalText","id":"talk.vc.home_wait_eldrie_9","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"如果您没有别的事情，那我要回去练剑了。","en":"If you have no business with me, then please let me return to my sword practice.","ja":"ご用がないようであれば剣の修業に戻らせていただきます"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eldrie_10#originalText","id":"talk.vc.home_wait_eldrie_10","speaker":{"cn":"艾尔多利耶","en":"Eldrie"},"text":{"cn":"失礼了，这样是否有欠礼数呢？但我突然想见见您。","en":"Pardon if I am intruding. I just wanted to see you."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eldrie_11#originalText","id":"talk.vc.home_wait_eldrie_11","speaker":{"cn":"艾尔多利耶","en":"Eldrie"},"text":{"cn":"很久没见到您了。看您生意兴盛，我也为之欣喜。","en":"I haven't seen you for a while. I am glad to see you are hard at work."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_entokia_integrator_1#originalText","id":"talk.vc.home_wait_entokia_integrator_1","speaker":{"cn":"恩特基尔","en":"Entokia","ja":"エントキア"},"text":{"cn":"轻松点，叫我恩基就好啦，这样我比较习惯。","en":"Please, just call me Enki! It suits me much better.","ja":"オレのことは、気軽にエンキって呼んでくださいよその方がしっくり来るんで"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_entokia_integrator_2#originalText","id":"talk.vc.home_wait_entokia_integrator_2","speaker":{"cn":"恩特基尔","en":"Entokia","ja":"エントキア"},"text":{"cn":"真羡慕老师这么自由呢，好希望我们能跟老师一样，自由前往那边的国家。","en":"You sure are lucky to be free, Master. I wish we were all free to travel abroad like you.","ja":"先生は自由でいいですなあオレたちも先生みたいに自由にあっちの国に行きたいっすわ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_entokia_integrator_3#originalText","id":"talk.vc.home_wait_entokia_integrator_3","speaker":{"cn":"恩特基尔","en":"Entokia","ja":"エントキア"},"text":{"cn":"那个《艾恩葛朗特流》你到底是在哪学的呢？我完全没听过。","en":"Where did you study that Aincrad style of yours? I've never even heard of it before.","ja":"その《アインクラッド流》はいったいどこで学ばれたんですかさっぱり聞いたことがないもんで"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_entokia_integrator_4#originalText","id":"talk.vc.home_wait_entokia_integrator_4","speaker":{"cn":"恩特基尔","en":"Entokia","ja":"エントキア"},"text":{"cn":"我的轰震枪很重喔，即使是老师恐怕也没办法轻易上手。","en":"My Roaring Thunder Spear is heavy, you know. I'm not sure that even you could wield it easily, Master.","ja":"オレの轟震槍は重いっすよさすがの先生でも少々手こずるんじゃないかと"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_entokia_integrator_9#originalText","id":"talk.vc.home_wait_entokia_integrator_9","speaker":{"cn":"恩特基尔","en":"Entokia","ja":"エントキア"},"text":{"cn":"老师，你在想好玩的事情对不对？也跟我分享一下嘛。","en":"Master, you've got something amusing on your mind, haven't you? Won't you share it with me?","ja":"先生、なんか楽しいこと考えてるでしょ?オレにも教えて下さいよ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugene_1#originalText","id":"talk.vc.home_wait_eugene_1","speaker":{"cn":"尤金","en":"Eugene","ja":"ユージーン"},"text":{"cn":"嗨，状况如何？要不要来比划一下？","en":"How's it going? Wanna have a practice-duel?","ja":"よう、調子はどうだ?ひとつ手合わせしてみないか?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugene_2#originalText","id":"talk.vc.home_wait_eugene_2","speaker":{"cn":"尤金","en":"Eugene","ja":"ユージーン"},"text":{"cn":"最近没几个对手打起来过瘾的。有没有哪里找得到强者啊？","en":"Know where there're any strong people to fight? I've been coming across nothing but weaklings lately.","ja":"最近は歯ごたえのあるヤツが少なくてなどこかに強いやつはいないのか?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugene_3#originalText","id":"talk.vc.home_wait_eugene_3","speaker":{"cn":"尤金","en":"Eugene","ja":"ユージーン"},"text":{"cn":"真没想到，居然会有和你并肩作战的一天。","en":"I never thought the day would come when you and I would join forces.","ja":"お前と肩を並べて戦う日が来るとはな"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugene_4#originalText","id":"talk.vc.home_wait_eugene_4","speaker":{"cn":"尤金","en":"Eugene","ja":"ユージーン"},"text":{"cn":"我想让你的那把剑……跟我的瓦兰姆竞争一次看看。","en":"Look at your sword... I'd like to see how my Demonic Sword Gram fares against it.","ja":"お前のその剣……俺のグラムと一度競わせてみたいものだ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugene_9#originalText","id":"talk.vc.home_wait_eugene_9","speaker":{"cn":"尤金","en":"Eugene","ja":"ユージーン"},"text":{"cn":"静静待着不符我的个性。我要去出任务了。","en":"Standing still doesn't suit me. I'm gonna go on a quest or something.","ja":"じっとしているのは性に合わんクエストにでも行くぞ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugene_10#originalText","id":"talk.vc.home_wait_eugene_10","speaker":{"cn":"尤金","en":"Eugene"},"text":{"cn":"喔喔，在此相遇是你气数已尽，快来跟我比划比划吧。","en":"Ooh! Let's have a practice-duel. I'm not letting you back out of this one!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugeo_1#originalText","id":"talk.vc.home_wait_eugeo_1","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"不知不觉间，我们两个像这样在一起，已经变成很理所当然的事情了。","en":"I don't know when it happened, but I can't imagine life without you now.","ja":"いつの間にか、こうしてふたりでいるのが当たり前になってたよ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugeo_2#originalText","id":"talk.vc.home_wait_eugeo_2","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"真是的，你不要老是乱来啦，也为阻止你的我想一想吧。","en":"Why do you always have to be so reckless? Put yourself in my shoes - I have a terrible time stopping you.","ja":"まったく、無茶ばっかりするなあ止めるこっちの身にもなってくれよ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugeo_3#originalText","id":"talk.vc.home_wait_eugeo_3","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"我会负责教你神圣术。你可不要想逃跑喔。","en":"I'll teach you the Sacred Arts. And I won't let you weasel out of it.","ja":"神聖術の方は、僕が教えるから逃げようとしてもだめだからね"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugeo_4#originalText","id":"talk.vc.home_wait_eugeo_4","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"前辈后辈这种事，卢利特的人并不在意。不过……好像也不错。","en":"I never really noticed apprentices and mentors much back in Rulid... But I think I like it.","ja":"先輩とか後輩って、ルーリッドではあんまり意識しなかったけど……なんか、いいね"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugeo_5#originalText","id":"talk.vc.home_wait_eugeo_5","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"我从没想过居然能砍倒《基家斯西达》，看来是自我设限了呢。","en":"I never even considered that I could chop down the Gigas Cedar. I was putting limitations on myself without even realizing it.","ja":"《ギガスシダー》を切り倒せるなんて思ってもみなかったんだ自分で限界を作っていたんだね"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugeo_6#originalText","id":"talk.vc.home_wait_eugeo_6","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"Stay cool吗？《艾恩葛朗特流》的招呼语还真有意思。还有其他的吗？","en":"Stay cool, huh? I like that Aincrad style saying. Are there any other sayings?","ja":"ステイ・クール、か《アインクラッド流》のあいさつって面白いね。ほかにどんなのがあるの? "},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugeo_7#originalText","id":"talk.vc.home_wait_eugeo_7","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"……你的眼睛很漂亮呢。","en":"Your eyes are really pretty.","ja":"……君の目ってすごくキレイだね"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugeo_8#originalText","id":"talk.vc.home_wait_eugeo_8","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"要不要去安静的地方呢？……我想跟你独处。","en":"Want to go some place quieter? I want us to be alone...","ja":"少し、静かなところに行かない?……ふたりになりたいんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugeo_9#originalText","id":"talk.vc.home_wait_eugeo_9","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"……我说，你不会又在想什么诡计了吧？","en":"You don't have ulterior motives, do you?","ja":"……またなにか悪巧みを考えてるんじゃないだろうね? "},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugeo_10#originalText","id":"talk.vc.home_wait_eugeo_10","speaker":{"cn":"尤吉欧","en":"Eugeo"},"text":{"cn":"只是稍微没看见你，就觉得好像过了很久呢。毕竟我们之前都形影不离嘛。","en":"Not seeing you for even a little while feels like ages. Because we've been together all this time."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugeo_11#originalText","id":"talk.vc.home_wait_eugeo_11","speaker":{"cn":"尤吉欧","en":"Eugeo"},"text":{"cn":"你好像有一段时间不在，去哪里了呢？","en":"Haven't seen you in a while. Where've you been?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugeo_12#originalText","id":"talk.vc.home_wait_eugeo_12","speaker":{"cn":"尤吉欧","en":"Eugeo"},"text":{"cn":"平安迎接新年了呢。今年也多多指教。","en":"Looks like we made it to another New Year. Hope it's a good one!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugeo_13#originalText","id":"talk.vc.home_wait_eugeo_13","speaker":{"cn":"尤吉欧","en":"Eugeo"},"text":{"cn":"我看外面装饰着鱼头，是某种诅咒吗？","en":"I see there's a fish head displayed outside. Is it some kind of curse?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugeo_14#originalText","id":"talk.vc.home_wait_eugeo_14","speaker":{"cn":"尤吉欧","en":"Eugeo"},"text":{"cn":"总觉得，来了一堆女孩子呢……","en":"Is it just me, or have the girls been giving us lots of attention today?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugeo_15#originalText","id":"talk.vc.home_wait_eugeo_15","speaker":{"cn":"尤吉欧","en":"Eugeo"},"text":{"cn":"小时候虽然有玩过人偶，但没有做得如此精巧。","en":"I remember playing with dolls when I was little, but they weren't this elaborate."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugeo_16#originalText","id":"talk.vc.home_wait_eugeo_16","speaker":{"cn":"尤吉欧","en":"Eugeo"},"text":{"cn":"你拿着那么大包的行李要去哪里？咦，那些全都是要给女孩子的礼物？","en":"Where are you going with such a big bag? Huh? Are all of those gifts for the girls?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugeo_17#originalText","id":"talk.vc.home_wait_eugeo_17","speaker":{"cn":"尤吉欧","en":"Eugeo"},"text":{"cn":"不可以说谎啦。骗人也没有好处啊。","en":"Lying is wrong. Nothing good can come from deceiving others."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugeo_18#originalText","id":"talk.vc.home_wait_eugeo_18","speaker":{"cn":"尤吉欧","en":"Eugeo"},"text":{"cn":"长假就是要来练剑啊。我必须要变得更强才行。","en":"I'd like to spend my long holidays training. I have to get much stronger and better with the sword."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugeo_19#originalText","id":"talk.vc.home_wait_eugeo_19","speaker":{"cn":"尤吉欧","en":"Eugeo"},"text":{"cn":"对《伐木手》来说，在雨天工作会很辛苦……所以心情总是会变得忧郁呢。","en":"Rainy days made my work as a \"carver\" really miserable... So rain always makes me feel gloomy."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugeo_20#originalText","id":"talk.vc.home_wait_eugeo_20","speaker":{"cn":"尤吉欧","en":"Eugeo"},"text":{"cn":"将写着愿望的签绑在树上……既然如此，我的愿望就只有一个。","en":"You write your wish on a slip of paper and tie it to a tree? Then I know what I want to wish for. I only have one wish."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugeo_21#originalText","id":"talk.vc.home_wait_eugeo_21","speaker":{"cn":"尤吉欧","en":"Eugeo"},"text":{"cn":"夏至祭典啊……卢利特也有喔，只是规模比较小。","en":"Summer Festival, eh? We had those in Rulid, too. Though they were really small in scale."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugeo_22#originalText","id":"talk.vc.home_wait_eugeo_22","speaker":{"cn":"尤吉欧","en":"Eugeo"},"text":{"cn":"你看！有多久没看过那么大的月亮了呢……","en":"Oh, look! When's the last time you saw the moon so big?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugeo_23#originalText","id":"talk.vc.home_wait_eugeo_23","speaker":{"cn":"尤吉欧","en":"Eugeo"},"text":{"cn":"Trick or……？那也是《艾恩葛朗特流》的招呼语吗？","en":"Trick or treat...? Is that another Aincrad saying?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugeo_24#originalText","id":"talk.vc.home_wait_eugeo_24","speaker":{"cn":"尤吉欧","en":"Eugeo"},"text":{"cn":"还在村子的时候，我从没想过要去观赏变红的叶子呢。","en":"Back in Rulid, I never considered sitting and looking at the trees in autumn."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugeo_25#originalText","id":"talk.vc.home_wait_eugeo_25","speaker":{"cn":"尤吉欧","en":"Eugeo"},"text":{"cn":"原来如此，是庆祝伟人诞辰的祭典啊。不过，那身红衣服又是怎么一回事？","en":"Oh. So it's the birthday of a very important man... But what's with the red costume?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugeo_child_1#originalText","id":"talk.vc.home_wait_eugeo_child_1","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"真的有白银的龙骑士吗……你觉得呢？","en":"Do you think the Silver Dragon Knight actually exists?","ja":"白銀の竜騎士、なんて本当に居るのかなあ……どう思う? "},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugeo_child_2#originalText","id":"talk.vc.home_wait_eugeo_child_2","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"好，下次我不会输的。下一次，我一定要让你请西拉鲁水！","en":"Okay, I'm not losing this time! This time for sure, you're treating me to siral water!","ja":"よーし、次は負けないぞ今度こそ、シラル水をおごってもらうんだから! "},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugeo_child_3#originalText","id":"talk.vc.home_wait_eugeo_child_3","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"我才不是优等生呢，是你太不认真了啦！","en":"I'm not exactly a star pupil. You're just a major slacker!","ja":"僕が優等生ってわけじゃないよそっちが不真面目すぎるんだ! "},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugeo_child_4#originalText","id":"talk.vc.home_wait_eugeo_child_4","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"总有一天……我是不是也能离开这个村子呢……","en":"I wonder if the day will come... when I also leave this village.","ja":"いつか……僕もこの村を出られる日が来るのかな……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugeo_child_9#originalText","id":"talk.vc.home_wait_eugeo_child_9","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"休息时间差不多该结束了。来，开始工作吧。","en":"Let's wrap up our break and get back to work!","ja":"休憩はそろそろ終わりにしようさあ、仕事を始めるよ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugeo_child_10#originalText","id":"talk.vc.home_wait_eugeo_child_10","speaker":{"cn":"尤吉欧","en":"Eugeo"},"text":{"cn":"啊，抱歉。我只是很好奇你在做什么……","en":"Oh! I'm sorry. I was just wondering how you're doing."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugeo_child_11#originalText","id":"talk.vc.home_wait_eugeo_child_11","speaker":{"cn":"尤吉欧","en":"Eugeo"},"text":{"cn":"我知道你很忙，但如果方便的话，要再来找我喔。","en":"I know you're probably busy, but come see me again if you want."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugeo_integrator_5#originalText","id":"talk.vc.home_wait_eugeo_integrator_5","speaker":{"cn":"集成骑士尤吉欧","en":"Integrity Knight Eugeo","ja":"整合騎士ユージオ"},"text":{"cn":"欠番","en":"欠番","ja":"欠番"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugeo_integrator_6#originalText","id":"talk.vc.home_wait_eugeo_integrator_6","speaker":{"cn":"集成骑士尤吉欧","en":"Integrity Knight Eugeo","ja":"整合騎士ユージオ"},"text":{"cn":"欠番","en":"欠番","ja":"欠番"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugeo_integrator_7#originalText","id":"talk.vc.home_wait_eugeo_integrator_7","speaker":{"cn":"集成骑士尤吉欧","en":"Integrity Knight Eugeo","ja":"整合騎士ユージオ"},"text":{"cn":"欠番","en":"欠番","ja":"欠番"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugeo_integrator_8#originalText","id":"talk.vc.home_wait_eugeo_integrator_8","speaker":{"cn":"集成骑士尤吉欧","en":"Integrity Knight Eugeo","ja":"整合騎士ユージオ"},"text":{"cn":"欠番","en":"欠番","ja":"欠番"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_fanatio_1#originalText","id":"talk.vc.home_wait_fanatio_1","speaker":{"cn":"法那提欧","en":"Fanatio","ja":"ファナティオ"},"text":{"cn":"在您出门前，请记得先跟我报告。","en":"Whenever you go out, please inform me first.","ja":"どこかへお出かけになる時は私に報告してからにしてください"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_fanatio_2#originalText","id":"talk.vc.home_wait_fanatio_2","speaker":{"cn":"法那提欧","en":"Fanatio","ja":"ファナティオ"},"text":{"cn":"如果您有空，是否可以请您跟我比划一下？","en":"If you have the time, may we have a practice-duel?","ja":"お時間がありましたら手合わせをお願いしてもよろしいですか"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_fanatio_3#originalText","id":"talk.vc.home_wait_fanatio_3","speaker":{"cn":"法那提欧","en":"Fanatio","ja":"ファナティオ"},"text":{"cn":"我接下来，要去监督《四旋剑》修练。","en":"I'm about to go observe the Four Whirling Blades at practice.","ja":"これから《四旋剣》の修練を見てきます"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_fanatio_4#originalText","id":"talk.vc.home_wait_fanatio_4","speaker":{"cn":"法那提欧","en":"Fanatio","ja":"ファナティオ"},"text":{"cn":"请您不要把我当成女性。受人怜悯……非我本意！","en":"Please don't think of me as a woman. I abhor pity!","ja":"私を女などと思わないでください情けをかけられるのは……不本意です!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_fanatio_9#originalText","id":"talk.vc.home_wait_fanatio_9","speaker":{"cn":"法那提欧","en":"Fanatio","ja":"ファナティオ"},"text":{"cn":"您看起来很累呢，是否该先稍事休息？","en":"You seem quite tired. Why don't you take a rest?","ja":"ずいぶんお疲れのようですね一度ゆっくり休まれては?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_fanatio_10#originalText","id":"talk.vc.home_wait_fanatio_10","speaker":{"cn":"法那提欧","en":"Fanatio"},"text":{"cn":"打扰了！法那提欧‧辛赛西斯‧滋，前来报到！","en":"Excuse me! Fanatio Synthesis Two has arrived!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_fanatio_11#originalText","id":"talk.vc.home_wait_fanatio_11","speaker":{"cn":"法那提欧","en":"Fanatio"},"text":{"cn":"原来您在这里。来，还有很多公务没做喔！","en":"Oh, there you are. Come, we have lots of work to do!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_fizel_1#originalText","id":"talk.vc.home_wait_fizel_1","speaker":{"cn":"费赛尔","en":"Fizel","ja":"フィゼル"},"text":{"cn":"我觉得心脏被刺穿比较轻松。会感觉身体渐渐变寒冷喔。","en":"I preferred being stabbed in the heart. It feels like you just get colder and colder while you die.","ja":"あたしは、心臓を刺されるのが楽だったな。だんだん体が冷たくなっていく感じがするの"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_fizel_2#originalText","id":"talk.vc.home_wait_fizel_2","speaker":{"cn":"费赛尔","en":"Fizel","ja":"フィゼル"},"text":{"cn":"什么法律还神圣术的，我受够念书了。好想赶快跟暗之军队战斗啊。","en":"I'm sick of all this studying of law and Sacred Arts! I just wanna fight Dark forces.","ja":"禁忌目録とか神聖術とかお勉強はもうこりごり早く闇の軍勢と戦いたいなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_fizel_3#originalText","id":"talk.vc.home_wait_fizel_3","speaker":{"cn":"费赛尔","en":"Fizel","ja":"フィゼル"},"text":{"cn":"我最看不惯比我们还弱的人，打着集成骑士的名号了！","en":"It's insulting when humans weaker than us pretend to be Integrity Knights!","ja":"あたしたちより弱い人が整合騎士を名乗ってるのが気に入らないのよ!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_fizel_4#originalText","id":"talk.vc.home_wait_fizel_4","speaker":{"cn":"费赛尔","en":"Fizel","ja":"フィゼル"},"text":{"cn":"这把毒剑，是亚多米尼史特蕾达大人赐予的喔！很棒吧？","en":"The Lady Administrator gave us this poisoned sword! Isn't it lovely?","ja":"この毒剣は、アドミニストレータ様がくださったのよ!いいでしょう?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_fizel_9#originalText","id":"talk.vc.home_wait_fizel_9","speaker":{"cn":"费赛尔","en":"Fizel","ja":"フィゼル"},"text":{"cn":"讨厌，你是怎么了啦？干嘛那么安静。","en":"Goodness, what's wrong? You're so quiet.","ja":"もう、どうしたのよ?静かになっちゃって"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_fizel_10#originalText","id":"talk.vc.home_wait_fizel_10","speaker":{"cn":"费赛尔","en":"Fizel"},"text":{"cn":"我是费赛尔喔。你应该不会跟我说你忘了吧？","en":"It's Fizel! Don't tell me you've forgotten?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_fizel_11#originalText","id":"talk.vc.home_wait_fizel_11","speaker":{"cn":"费赛尔","en":"Fizel"},"text":{"cn":"我对你的实力有兴趣。所以你偶尔也要来我们这里喔。","en":"I am intrigued by the source of your power. So you should come visit us from time to time."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_frenica_1#originalText","id":"talk.vc.home_wait_frenica_1","speaker":{"cn":"芙蕾妮卡","en":"Frenica","ja":"フレニーカ"},"text":{"cn":"我说啊，下一个安息日要不要一起出门走走？","en":"Since it's a day of rest, want to go out somewhere?","ja":"ねえ、次の安息日は、どこかに出かけない?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_frenica_2#originalText","id":"talk.vc.home_wait_frenica_2","speaker":{"cn":"芙蕾妮卡","en":"Frenica","ja":"フレニーカ"},"text":{"cn":"希望有一天，我也能跟学长们一样强。","en":"I hope I can become just as strong as you someday.","ja":"いつか私も、先輩たちみたいに強くなれたらいいな"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_frenica_3#originalText","id":"talk.vc.home_wait_frenica_3","speaker":{"cn":"芙蕾妮卡","en":"Frenica","ja":"フレニーカ"},"text":{"cn":"神圣术……比起剑术，我可能比较适合那个。","en":"Sacred Arts... I think I'm more cut out for that than for Sword Arts.","ja":"神聖術……私は剣術よりそっちのほうが向いてるのかも"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_frenica_4#originalText","id":"talk.vc.home_wait_frenica_4","speaker":{"cn":"芙蕾妮卡","en":"Frenica","ja":"フレニーカ"},"text":{"cn":"我也要进步，对于不喜欢的事，要变得能够明确地拒绝才行。","en":"I need to learn how to say no when I don't like something.","ja":"私も、イヤなことはイヤだってちゃんと言えるようにならないと"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_frenica_9#originalText","id":"talk.vc.home_wait_frenica_9","speaker":{"cn":"芙蕾妮卡","en":"Frenica","ja":"フレニーカ"},"text":{"cn":"……你好像已经累了嘛。今天就先休息吧？","en":"You seem tired. Want to take the day off?","ja":"……なんか疲れているみたいね今日はもう休んだら?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_frenica_10#originalText","id":"talk.vc.home_wait_frenica_10","speaker":{"cn":"芙蕾妮卡","en":"Frenica"},"text":{"cn":"啊……对、对不起。我有点，迷路……我先告辞了！","en":"Oh...s-sorry! I just got lost. Excuse me!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_geero_1#originalText","id":"talk.vc.home_wait_geero_1","speaker":{"cn":"吉罗","en":"Geero","ja":"ジーロ"},"text":{"cn":"吉罗·辛赛西斯·托尼佛作为四只剑的其一我会尽全力战斗到最后一刻","en":"I, Geero Synthesis Twenty-Four of the Four Whirling Blades, will show you the extent of my power!","ja":"ジーロ・シンセシス・トゥエニフォー四本の剣の一振りとして全力で戦い抜きます"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_geero_2#originalText","id":"talk.vc.home_wait_geero_2","speaker":{"cn":"吉罗","en":"Geero","ja":"ジーロ"},"text":{"cn":"想要不留任何一点后悔就只有不停努力这个方法而已","en":"I’m only doing this to avoid any regrets.","ja":"一片の後悔も残さぬようひたすらに努力し続けるのみです"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_geero_3#originalText","id":"talk.vc.home_wait_geero_3","speaker":{"cn":"吉罗","en":"Geero","ja":"ジーロ"},"text":{"cn":"我们获赐神器的那天会到来吗……","en":"I wonder if we’ll ever be bestowed divine weapons...","ja":"我らもいつか神器を賜る日が来るでしょうか……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_geero_4#originalText","id":"talk.vc.home_wait_geero_4","speaker":{"cn":"吉罗","en":"Geero","ja":"ジーロ"},"text":{"cn":"请往您觉得正确的道路前进吧我们会跟随您到天涯海角","en":"Follow the path you believe is right. We’ll always be here to assist you.","ja":"正しいと思う道をお進みください我らはどこまでもお供いたします"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_geero_9#originalText","id":"talk.vc.home_wait_geero_9","speaker":{"cn":"吉罗","en":"Geero","ja":"ジーロ"},"text":{"cn":"我们四旋剑会一直守在你们的身边","en":"We, the Four Whirling Blades, are always with you.","ja":"我ら四旋剣はいつも貴方様のお傍に"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_geero_10#originalText","id":"talk.vc.home_wait_geero_10","speaker":{"cn":"吉罗","en":"Geero"},"text":{"cn":"有没有任何忙是我们能帮的呢","en":"How may I be of assistance?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_golgorosso_1#originalText","id":"talk.vc.home_wait_golgorosso_1","speaker":{"cn":"哥鲁哥罗索","en":"Golgorosso","ja":"ゴルゴロッソ"},"text":{"cn":"如何？你有持续锻炼吗？毕竟是你，我想不会偷懒就是。","en":"Have you kept up with your training? Knowing you, I'm pretty sure the answer is yes.","ja":"どうだ、鍛錬は続いているか?お前のことだから、大丈夫だと思うがな"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_golgorosso_2#originalText","id":"talk.vc.home_wait_golgorosso_2","speaker":{"cn":"哥鲁哥罗索","en":"Golgorosso","ja":"ゴルゴロッソ"},"text":{"cn":"你锻炼得很扎实呢，我心里踏实多了！","en":"You've been training pretty hard. That's reassuring!","ja":"ずいぶん鍛えているな心強いぞ!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_golgorosso_3#originalText","id":"talk.vc.home_wait_golgorosso_3","speaker":{"cn":"哥鲁哥罗索","en":"Golgorosso","ja":"ゴルゴロッソ"},"text":{"cn":"如果是你，应该可以穷究《瓦尔提欧流》心法吧……","en":"I'm sure you have it in you to master the secrets of Baltio style.","ja":"《バルティオ流》の極意お前なら極められるだろう……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_golgorosso_4#originalText","id":"talk.vc.home_wait_golgorosso_4","speaker":{"cn":"哥鲁哥罗索","en":"Golgorosso","ja":"ゴルゴロッソ"},"text":{"cn":"好，我来帮你查看身材吧。把衣服脱掉。","en":"Okay, take off your clothes. Let me see those muscles.","ja":"よし、体を見てやろう服を脱げ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_golgorosso_9#originalText","id":"talk.vc.home_wait_golgorosso_9","speaker":{"cn":"哥鲁哥罗索","en":"Golgorosso","ja":"ゴルゴロッソ"},"text":{"cn":"你在冥想吗？为了锻炼身心，那也是不可或缺的行为呢。","en":"Meditation? That is also an important practice for developing a strong body and mind.","ja":"瞑想か?それも心身を鍛えるのに必要な行為だな"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_golgorosso_10#originalText","id":"talk.vc.home_wait_golgorosso_10","speaker":{"cn":"哥鲁哥罗索","en":"Golgorosso"},"text":{"cn":"打扰了。你偶尔也来我这里锻炼一下如何？","en":"Pardon the interruption. Won't you come train with me from time to time?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_heathcliff_1#originalText","id":"talk.vc.home_wait_heathcliff_1","speaker":{"cn":"希兹克利夫","en":"Heathcliff","ja":"ヒースクリフ"},"text":{"cn":"我想跟你比试一下，想以近距离看看你的《二刀流》剑法。","en":"I want to try and compete against you. Please show me your \"Two-sword Syle\" up close.","ja":"君とはぜひ立ち合ってみたい《二刀流》の剣さばきを至近距離で見てみたくてな"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_heathcliff_2#originalText","id":"talk.vc.home_wait_heathcliff_2","speaker":{"cn":"希兹克利夫","en":"Heathcliff","ja":"ヒースクリフ"},"text":{"cn":"我们一直都在招募能成为战力的人，像你这么强的玩家更是求之不得。","en":"We're always looking to recruit those with a fighting spirit. Especially players as strong as you.","ja":"戦力となる者は常に募集中だ君のような強いプレイヤーは特にね"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_heathcliff_3#originalText","id":"talk.vc.home_wait_heathcliff_3","speaker":{"cn":"希兹克利夫","en":"Heathcliff","ja":"ヒースクリフ"},"text":{"cn":"就算不一一发出指示，只要是我公会的成员，就一定不会有问题。","en":"Even if detailed instructions are not provided, our guild members won't have any problems.","ja":"いちいち指示を出さなくても我がギルドのメンバーなら問題あるまいよ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_heathcliff_4#originalText","id":"talk.vc.home_wait_heathcliff_4","speaker":{"cn":"希兹克利夫","en":"Heathcliff","ja":"ヒースクリフ"},"text":{"cn":"但是，你的反应速度真的非比寻常。这就连我的计算也……","en":"However, your reaction speed is abnormal This is faster than my calculations...","ja":"しかし、君の反応速度は尋常ではないこれは私の計算よりも……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_heathcliff_9#originalText","id":"talk.vc.home_wait_heathcliff_9","speaker":{"cn":"希兹克利夫","en":"Heathcliff","ja":"ヒースクリフ"},"text":{"cn":"不太明白你在想什么呢。为什么不想加入公会呢？","en":"You're not an easy one to catch. Why are you so against joining the guild?","ja":"君はなかなか捕まらないなどうして、ギルドに入ることを嫌うのかね?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_hoveren_1#originalText","id":"talk.vc.home_wait_hoveren_1","speaker":{"cn":"何布雷恩","en":"Hoveren","ja":"ホーブレン"},"text":{"cn":"让四旋剑挥上一剑吧我已经做好战斗到生命尽头的觉悟了","en":"The Four Whirling Blades are prepared to fight till death.","ja":"四旋剣が一振りとして命燃え尽きるまで戦う覚悟です"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_hoveren_2#originalText","id":"talk.vc.home_wait_hoveren_2","speaker":{"cn":"何布雷恩","en":"Hoveren","ja":"ホーブレン"},"text":{"cn":"能一起站在战场上……应该没有比这更光荣的事了","en":"Fighting alongside you is but the greatest honor.","ja":"共に戦場に立てる……これ以上に光栄なことはありません"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_hoveren_3#originalText","id":"talk.vc.home_wait_hoveren_3","speaker":{"cn":"何布雷恩","en":"Hoveren","ja":"ホーブレン"},"text":{"cn":"如果设置了极限那也就到此为止了我会变得更强！","en":"This is as far as I can go. But I will become stronger!","ja":"限界を決めてしまってはそれまでですもっと強くなってみせます!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_hoveren_4#originalText","id":"talk.vc.home_wait_hoveren_4","speaker":{"cn":"何布雷恩","en":"Hoveren","ja":"ホーブレン"},"text":{"cn":"在法那提欧大人的身边我会谨记不惜日夜的努力！","en":"Let it be day or night, I will forever be at Lord Fanatio’s disposal!","ja":"ファナティオ様の元、日夜弛まぬ努力を心がけて参ります!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_hoveren_9#originalText","id":"talk.vc.home_wait_hoveren_9","speaker":{"cn":"何布雷恩","en":"Hoveren","ja":"ホーブレン"},"text":{"cn":"有什么担心的事吗……？若我们帮得上忙的话不论何时都跟我们说吧","en":"Is something the matter...? Come to us if you ever need our help.","ja":"何か心配事がおありですか……?我らでお力になれるならば何時でもご用命ください"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_hoveren_10#originalText","id":"talk.vc.home_wait_hoveren_10","speaker":{"cn":"何布雷恩","en":"Hoveren"},"text":{"cn":"若要磨练《环刃旋舞》的技能，有没有什么比较有效的训练方法呢？","en":"Do you know some effective training to make Whirling Sword Dance stronger?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_humbert_1#originalText","id":"talk.vc.home_wait_humbert_1","speaker":{"cn":"温贝尔","en":"Humbert","ja":"ウンベール"},"text":{"cn":"老子……不，我居然输给那群乡下剑士！","en":"I would never lose to the likes of those two country scum!","ja":"あんな田舎剣士どもに負けるオレ……いや、私ではない!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_humbert_2#originalText","id":"talk.vc.home_wait_humbert_2","speaker":{"cn":"温贝尔","en":"Humbert","ja":"ウンベール"},"text":{"cn":"这个国家，是由身为贵族的我们在支撑着的！","en":"This kingdom is held up by noblemen like us!","ja":"この国は、貴族である私たちが支えているのだ!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_humbert_3#originalText","id":"talk.vc.home_wait_humbert_3","speaker":{"cn":"温贝尔","en":"Humbert","ja":"ウンベール"},"text":{"cn":"不管下贱的东西说了什么，都跟我没关系。","en":"The words of the low-born are of no concern to me.","ja":"下賤の物が何を言おうと私には関係のないことだ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_humbert_4#originalText","id":"talk.vc.home_wait_humbert_4","speaker":{"cn":"温贝尔","en":"Humbert","ja":"ウンベール"},"text":{"cn":"谁都不能对老子……对我出手，只能乖乖吞下去。","en":"No one will lay a finger on me. Falling back respectfully is our only course of action.","ja":"誰もオレ……私には手を出せないおとなしく引っ込むしかないのだ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_humbert_9#originalText","id":"talk.vc.home_wait_humbert_9","speaker":{"cn":"温贝尔","en":"Humbert","ja":"ウンベール"},"text":{"cn":"你今天还真安静。忘了怎么说话吗？","en":"You're unusually quiet today. Have you forgotten how to speak?","ja":"今日はやけに静かだな喋り方を忘れたのか?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_humbert_10#originalText","id":"talk.vc.home_wait_humbert_10","speaker":{"cn":"温贝尔","en":"Humbert"},"text":{"cn":"老子……我是温贝尔，你给我记住了！","en":"My name is Humbert. Don't you ever forget it!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_iskahn_1#originalText","id":"talk.vc.home_wait_iskahn_1","speaker":{"cn":"伊斯卡恩","en":"Iskahn","ja":"イスカーン"},"text":{"cn":"你看似高尚，实际里面却跟我一样。只想着一件事。","en":"Though you look like the elegant type, you're just like me. There's only one thing that I can think of.","ja":"お前、上品そうに見えて中身は俺と同じだなひとつのことしか考えてねえ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_iskahn_2#originalText","id":"talk.vc.home_wait_iskahn_2","speaker":{"cn":"伊斯卡恩","en":"Iskahn","ja":"イスカーン"},"text":{"cn":"你不会以为已经赢过我了吧？我们还没分出胜负呀！","en":"Do you think you've bested me? No, right? Because the fight has only just begun!","ja":"まさか俺に勝ったと思ってんじゃねえだろうな?まだ勝負はついてねえからな!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_iskahn_3#originalText","id":"talk.vc.home_wait_iskahn_3","speaker":{"cn":"伊斯卡恩","en":"Iskahn","ja":"イスカーン"},"text":{"cn":"喔，你有时间的话，就陪我练习吧。","en":"Oi, if you're free join me for practice.","ja":"おう、時間があるんだったら稽古に付き合え"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_iskahn_4#originalText","id":"talk.vc.home_wait_iskahn_4","speaker":{"cn":"伊斯卡恩","en":"Iskahn","ja":"イスカーン"},"text":{"cn":"看着你，我就……有种很奇怪的感觉！","en":"Whenever I see you... My mood just gets messed up!","ja":"お前を見てると、なんかこう……気分がおかしくなるんだよ!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_iskahn_9#originalText","id":"talk.vc.home_wait_iskahn_9","speaker":{"cn":"伊斯卡恩","en":"Iskahn","ja":"イスカーン"},"text":{"cn":"你！你别无视我啊！喂！","en":"Hey, you! Don't you dare ignore me!","ja":"お前! 俺のこと無視してんじゃねえぞ、おい!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_jace_1#originalText","id":"talk.vc.home_wait_jace_1","speaker":{"cn":"杰伊斯","en":"Jayce","ja":"ジェイス"},"text":{"cn":"我一直都有把身为骑士的使命挂在心上！","en":"As a knight, I vow to carry out my mission!","ja":"騎士として、果たすべき使命は心得ております!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_jace_2#originalText","id":"talk.vc.home_wait_jace_2","speaker":{"cn":"杰伊斯","en":"Jayce","ja":"ジェイス"},"text":{"cn":"我准备好了随时可以上场！","en":"I’m ready to go at any time!","ja":"準備は万全ですいつでも出れます!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_jace_3#originalText","id":"talk.vc.home_wait_jace_3","speaker":{"cn":"杰伊斯","en":"Jayce","ja":"ジェイス"},"text":{"cn":"我们的应该能更加磨练剑术，我们不满足于现状会继续精进！","en":"There should be no limit to our swords’ power. I must throw away my pride and apply myself!","ja":"我らの剣はまだ磨くことができるはず慢心せず精進いたします!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_jace_4#originalText","id":"talk.vc.home_wait_jace_4","speaker":{"cn":"杰伊斯","en":"Jayce","ja":"ジェイス"},"text":{"cn":"一起流汗，把肩膀交给彼此有同伴这件事，每次都拯救了我","en":"We’re evenly matched. I’m always glad to have an partner with equal skill.","ja":"共に汗を流し、肩を並べる仲間がいることにいつも助けられています"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_jace_9#originalText","id":"talk.vc.home_wait_jace_9","speaker":{"cn":"杰伊斯","en":"Jayce","ja":"ジェイス"},"text":{"cn":"您不累吗？我帮您拿希拉尔水来吧","en":"Are you tired? Should I bring you some siral water?","ja":"お疲れではないですか?シラル水をお持ちしましょうか"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_jace_10#originalText","id":"talk.vc.home_wait_jace_10","speaker":{"cn":"杰伊斯","en":"Jayce"},"text":{"cn":"有什么问题的话随时都可以跟我说","en":"You can come to me if you ever need anything."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kagemune_1#originalText","id":"talk.vc.home_wait_kagemune_1","speaker":{"cn":"影宗","en":"Kagemune","ja":"カゲムネ"},"text":{"cn":"哎呀，只要一想到你是我的伙伴，心里就觉得踏实呢。请多关照。","en":"I feel safer knowing you're on my side! Thanks for joining me, buddy.","ja":"やあ、君が仲間だと思うと心強いよよろしく頼む"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kagemune_2#originalText","id":"talk.vc.home_wait_kagemune_2","speaker":{"cn":"影宗","en":"Kagemune","ja":"カゲムネ"},"text":{"cn":"魔法技能差不多快提升了，下次你愿意陪我出任务吗？","en":"Will you go on a quest with me soon? My magic skill is about to increase.","ja":"そろそろ魔法スキルが上がるから今度クエストに付き合ってくれないか?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kagemune_3#originalText","id":"talk.vc.home_wait_kagemune_3","speaker":{"cn":"影宗","en":"Kagemune","ja":"カゲムネ"},"text":{"cn":"飞在空中的感觉很不错吧？要是在那边也能飞就好了。","en":"It sure feels good to fly. I wish we could fly for real.","ja":"空を飛ぶ感覚っていいよなあっち側でも飛べたらいいのに"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kagemune_4#originalText","id":"talk.vc.home_wait_kagemune_4","speaker":{"cn":"影宗","en":"Kagemune","ja":"カゲムネ"},"text":{"cn":"依照合作的方式，甚至有可能打赢强大的对手。所以得要好好珍惜伙伴啊。","en":"If you surround yourself with the right people, you can beat enemies that are even stronger than you! That's why you should treat your allies well.","ja":"連携次第で、強いヤツにも勝てるだから仲間ってのは大事にしないとな"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kagemune_9#originalText","id":"talk.vc.home_wait_kagemune_9","speaker":{"cn":"影宗","en":"Kagemune","ja":"カゲムネ"},"text":{"cn":"呼啊……我们彼此都好闲啊。","en":"Ahhh. We’ve got nothing to do.","ja":"ふわ……ぁ暇だな、お互いに"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kagemune_10#originalText","id":"talk.vc.home_wait_kagemune_10","speaker":{"cn":"影宗","en":"Kagemune"},"text":{"cn":"哎呀，我是不是打扰到你啦？抱歉抱歉，我不小心迷路了。","en":"Oops, did I interrupt something? Sorry, my bad. I was just a bit lost."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kibaou_1#originalText","id":"talk.vc.home_wait_kibaou_1","speaker":{"cn":"牙王","en":"Kibaou","ja":"キバオウ"},"text":{"cn":"怎么，找我有什么事吗？","en":"What? You have business with me?","ja":"なんや、わいになんか用か?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kibaou_2#originalText","id":"talk.vc.home_wait_kibaou_2","speaker":{"cn":"牙王","en":"Kibaou","ja":"キバオウ"},"text":{"cn":"哼……我会用自己的方式去做。","en":"Hmph. I'll do my own thing.","ja":"ふん……わいはわいのやり方でやらせてもらうで"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kibaou_3#originalText","id":"talk.vc.home_wait_kibaou_3","speaker":{"cn":"牙王","en":"Kibaou","ja":"キバオウ"},"text":{"cn":"你不要误会，我不是为了你才在这里的。","en":"Don't get the wrong idea. I'm not here to help you.","ja":"勘違いしたらあかんで今ここにおるんは、お前のためやないんや"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kibaou_4#originalText","id":"talk.vc.home_wait_kibaou_4","speaker":{"cn":"牙王","en":"Kibaou","ja":"キバオウ"},"text":{"cn":"总有一天我要赢过你。你就把脖子洗干净等着吧。","en":"I'll beat ya someday. Wipe your ass, 'cause it's gonna get kicked!","ja":"いつかお前に勝ってやるからな首洗って待っとけよ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kibaou_9#originalText","id":"talk.vc.home_wait_kibaou_9","speaker":{"cn":"牙王","en":"Kibaou","ja":"キバオウ"},"text":{"cn":"别闷不吭声的，来个聊得开的话题如何？","en":"Why dontcha talk about something, instead of being quiet?","ja":"黙っとらんと、気の利いた話でもしたらどうや?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kibaou_10#originalText","id":"talk.vc.home_wait_kibaou_10","speaker":{"cn":"牙王","en":"Kibaou"},"text":{"cn":"为什么！你为什么要无视我！","en":"Why're you ignoring me?!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kirito_1#originalText","id":"talk.vc.home_wait_kirito_1","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"嗨，我正想见你呢。","en":"Hey, there! I was hoping you'd show up.","ja":"よう、ちょうど会いたいと思ってたんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kirito_2#originalText","id":"talk.vc.home_wait_kirito_2","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"我们来打赌吧。先吃到对方一击的人就要请饮料，如何？","en":"Let's make a bet. Whoever gets in the first hit gets a free drink from the loser. How does that sound?","ja":"賭けをしようぜ先に1本取られたほうが飲み物奢るってのはどうだ?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kirito_3#originalText","id":"talk.vc.home_wait_kirito_3","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"哦，你来得正好！要不要来一起练习，挥洒汗水啊？","en":"Ooh, perfect timing! Wanna go work up a sweat in the practice room?","ja":"お、いいところに!これから稽古で一汗かかないか?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kirito_4#originalText","id":"talk.vc.home_wait_kirito_4","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"我才不是什么英雄呢，我只是……想守护大家罢了。","en":"I'm no hero. I just...want to protect people.","ja":"俺は英雄なんかじゃないさただ……守りたいんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kirito_5#originalText","id":"talk.vc.home_wait_kirito_5","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"哇哇哇哇哇……！就说我没偷藏东西啦！！好啦～来整理个房间好了……","en":"Whoa, there! I'm not hiding anything, I swear! Well, then, I guess I'll clean the room or something...","ja":"わわわわわ……!何にも隠してないって!!さぁ部屋でも片付けるかな……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kirito_6#originalText","id":"talk.vc.home_wait_kirito_6","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"嗨！你在做什么啊？","en":"Hi! Whatcha doin’?","ja":"よう!何してるんだ?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kirito_7#originalText","id":"talk.vc.home_wait_kirito_7","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"指尖很冷吗？我来用手帮你取暖吧。","en":"Are your fingers cold? Let me help keep you warm.","ja":"指先が冷えるのか?俺の手で温めてやるよ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kirito_8#originalText","id":"talk.vc.home_wait_kirito_8","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"要不要偶尔就我们两个去哪走走啊？","en":"Wanna go out somewhere? It's been a while.","ja":"たまにはふたりでどっか行かないか?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kirito_9#originalText","id":"talk.vc.home_wait_kirito_9","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"嗯～接下来该做什么好呢？","en":"Okay. What should I do now?","ja":"さて、これからどうしようかな"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kirito_10#originalText","id":"talk.vc.home_wait_kirito_10","speaker":{"cn":"桐人","en":"Kirito"},"text":{"cn":"总觉得很久没碰面耶？你偶尔也该想起我一下啦。","en":"Hey, it's been a while. At least remember me from time to time, will ya?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kirito_11#originalText","id":"talk.vc.home_wait_kirito_11","speaker":{"cn":"桐人","en":"Kirito"},"text":{"cn":"嗨。因为我想见你，就绕过来看看了。","en":"Hey! I wanted to see you, so I swung by."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kirito_12#originalText","id":"talk.vc.home_wait_kirito_12","speaker":{"cn":"桐人","en":"Kirito"},"text":{"cn":"我们去新年参拜吧～！！啊，所谓的新年参拜，是指刚过新年就去跟神明许愿啦。","en":"Let's go to Hatsumode together! Oh, Hatsumode is where you go to a shrine on New Year's Day to pray."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kirito_13#originalText","id":"talk.vc.home_wait_kirito_13","speaker":{"cn":"桐人","en":"Kirito"},"text":{"cn":"鬼～出去！福～～进来！","en":"Time to celebrate Setsubun by throwing some beans! Demons out! Good fortune in!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kirito_14#originalText","id":"talk.vc.home_wait_kirito_14","speaker":{"cn":"桐人","en":"Kirito"},"text":{"cn":"总觉得今天每个女孩子都定不下心耶。","en":"All the girls seem nervous today. I wonder why?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kirito_15#originalText","id":"talk.vc.home_wait_kirito_15","speaker":{"cn":"桐人","en":"Kirito"},"text":{"cn":"这两个人偶代表新娘跟新郎，是用来祈求与祝福女孩子成长喔。","en":"These are bride and groom dolls for Hinamatsuri. We use these dolls to wish girls an auspicious journey to adulthood."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kirito_16#originalText","id":"talk.vc.home_wait_kirito_16","speaker":{"cn":"桐人","en":"Kirito"},"text":{"cn":"那么，接下来要到谁那里去呢？","en":"Okay. Who should I go see next?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kirito_17#originalText","id":"talk.vc.home_wait_kirito_17","speaker":{"cn":"桐人","en":"Kirito"},"text":{"cn":"我不是在骗人，是开玩笑啦。用来取悦人的玩笑不算罪过吧？","en":"It's not a lie, it's a joke. Just joking to lighten up the mood. That's not a sin, last I checked."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kirito_18#originalText","id":"talk.vc.home_wait_kirito_18","speaker":{"cn":"桐人","en":"Kirito"},"text":{"cn":"嗨。难得放假，我们偶尔也出远门吧！","en":"Hey, there! We haven't had a day off in ages. Let's go out somewhere special!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kirito_19#originalText","id":"talk.vc.home_wait_kirito_19","speaker":{"cn":"桐人","en":"Kirito"},"text":{"cn":"你来得正好！我忘了带伞，一起回去吧。","en":"Ooh, perfect timing! I forgot my umbrella. Can I walk home with you?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kirito_20#originalText","id":"talk.vc.home_wait_kirito_20","speaker":{"cn":"桐人","en":"Kirito"},"text":{"cn":"你在这上面写下愿望吧。这样一来，愿望就一定会实现。","en":"Write your wish on this piece of paper for Tanabata. I just know your wish will come true."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kirito_21#originalText","id":"talk.vc.home_wait_kirito_21","speaker":{"cn":"桐人","en":"Kirito"},"text":{"cn":"好热──天气这么热，就会让人想去海边呢……","en":"Dude, it's so hot out! Makes me wanna go to the beach."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kirito_22#originalText","id":"talk.vc.home_wait_kirito_22","speaker":{"cn":"桐人","en":"Kirito"},"text":{"cn":"喂～今晚一起赏月吧！","en":"Hellooo! It's a full moon tonight. Let's watch it together!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kirito_23#originalText","id":"talk.vc.home_wait_kirito_23","speaker":{"cn":"桐人","en":"Kirito"},"text":{"cn":"我们一起来扮装吧！不，这不是米尼翁啦！","en":"Hey, let's dress up! This isn't a minion costume, FYI!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kirito_24#originalText","id":"talk.vc.home_wait_kirito_24","speaker":{"cn":"桐人","en":"Kirito"},"text":{"cn":"树叶全都转红了，我们一起去看看吧。就是所谓的赏枫喔。","en":"The leaves are starting to turn red for autumn, so we should go for a drive to look at them! It's called Momijigari."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kirito_25#originalText","id":"talk.vc.home_wait_kirito_25","speaker":{"cn":"桐人","en":"Kirito"},"text":{"cn":"圣诞快乐！这东西叫圣诞树喔。来嘛，你也放些装饰上去。","en":"Merry Christmas! I got us a Christmas tree. Come on, let's put on some ornaments!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kirito_child_1#originalText","id":"talk.vc.home_wait_kirito_child_1","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"嗨，今天想去哪里呢？","en":"Hi. Where're we going today?","ja":"よう、今日はどこに行く? "},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kirito_child_2#originalText","id":"talk.vc.home_wait_kirito_child_2","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"我们去找找看有没有好玩的事情吧！","en":"Let's go out and see if we can find something fun!","ja":"何か面白いこと探しに行こうぜ! "},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kirito_child_3#originalText","id":"talk.vc.home_wait_kirito_child_3","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"嘿嘿……我们以后也要一直在一起喔！","en":"Hehe. We'll be best friends forever!","ja":"へへ……俺たちは、これからもずっと一緒だぜ! "},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kirito_child_4#originalText","id":"talk.vc.home_wait_kirito_child_4","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"嗯～我很不擅长神圣术呢……","en":"Grrr. I'm just not very good at Sacred Arts.","ja":"うーん、神聖術ってのはどうも苦手だなあ……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kirito_child_9#originalText","id":"talk.vc.home_wait_kirito_child_9","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"喂喂，你怎么了？肚子痛吗？","en":"Hey, what's wrong? Got a tummy ache?","ja":"おいおい、どうしたんだ? 腹でも痛いのか? "},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kirito_child_10#originalText","id":"talk.vc.home_wait_kirito_child_10","speaker":{"cn":"桐人","en":"Kirito"},"text":{"cn":"咦，好像很久没看到你了。你最近好吗？","en":"How've you been? I haven't seen you in a long time."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kirito_child_11#originalText","id":"talk.vc.home_wait_kirito_child_11","speaker":{"cn":"桐人","en":"Kirito"},"text":{"cn":"喂喂，你偶尔也该叫上我吧！","en":"Hey, now! Call on me once in a while, will ya?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_klein_1#originalText","id":"talk.vc.home_wait_klein_1","speaker":{"cn":"克莱因","en":"Klein","ja":"クライン"},"text":{"cn":"实在是很不可思议的世界耶，这个叫Alicization的……","en":"Man, the Alicization world is just weird and mysterious all around.","ja":"なんとも不思議な世界だなあアンダーワールドってのはよぉ……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_klein_2#originalText","id":"talk.vc.home_wait_klein_2","speaker":{"cn":"克莱因","en":"Klein","ja":"クライン"},"text":{"cn":"如果有什么烦恼，要赶紧跟我说喔。","en":"If something is troubling you, tell me right away.","ja":"なんか困ったことがあったらすぐオレに言えよ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_klein_3#originalText","id":"talk.vc.home_wait_klein_3","speaker":{"cn":"克莱因","en":"Klein","ja":"クライン"},"text":{"cn":"等级跟状态都没有显示出来，很难判断强度耶。","en":"There's no level or stats displays? Man, how can you tell how powerful anyone is?","ja":"レベルも、ステータスも表示がねえ強さがわかりづれぇなぁ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_klein_4#originalText","id":"talk.vc.home_wait_klein_4","speaker":{"cn":"克莱因","en":"Klein","ja":"クライン"},"text":{"cn":"你每次都在勉强自己嘛，我放不下心啦……","en":"You always push yourself too hard, buddy. Jeez, high-maintenance, much?","ja":"オメエはいっつも無理するからな放っておけねえんだよ……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_klein_9#originalText","id":"talk.vc.home_wait_klein_9","speaker":{"cn":"克莱因","en":"Klein","ja":"クライン"},"text":{"cn":"喂喂，你干嘛不说话啦？不是有事找我吗？","en":"Whoa, dude, why're you so quiet? Didn't you want something from me?","ja":"おいおい、何だよ黙っちまってなんか、用事があるんじゃなかったのか?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_klein_10#originalText","id":"talk.vc.home_wait_klein_10","speaker":{"cn":"克莱因","en":"Klein"},"text":{"cn":"嗨！一阵子不见，你看起来过得还不错嘛。","en":"Sup! Haven't seen you in a while. Glad you're lookin' good."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_klein_11#originalText","id":"talk.vc.home_wait_klein_11","speaker":{"cn":"克莱因","en":"Klein"},"text":{"cn":"喂，你也偶尔回来露个脸吧。","en":"Hey! At least say hi once in a while?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kuradeel_1#originalText","id":"talk.vc.home_wait_kuradeel_1","speaker":{"cn":"克拉帝尔","en":"Kuradeel","ja":"クラディール"},"text":{"cn":"我的任务是保护你……为此，我会不择手段。","en":"My mission is to protect you. And I will do so, at any cost.","ja":"私の任務は、あなたを守ること……そのためならば、手段は選びません"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kuradeel_2#originalText","id":"talk.vc.home_wait_kuradeel_2","speaker":{"cn":"克拉帝尔","en":"Kuradeel","ja":"クラディール"},"text":{"cn":"那位大人真是……有点任性过头了啊……","en":"Goodness. That person is just a little too selfish.","ja":"まったくあの方は……少しわがままが過ぎるな……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kuradeel_3#originalText","id":"talk.vc.home_wait_kuradeel_3","speaker":{"cn":"克拉帝尔","en":"Kuradeel","ja":"クラディール"},"text":{"cn":"呵呵……要是没有时时刻刻张望，说不定哪天危险就会找上门嘛。","en":"Hehe... You should always keep your guard up. There's no telling when danger might strike.","ja":"ふふ……常に見張っておかなければいつ危険が迫るともしれないからな"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kuradeel_4#originalText","id":"talk.vc.home_wait_kuradeel_4","speaker":{"cn":"克拉帝尔","en":"Kuradeel","ja":"クラディール"},"text":{"cn":"我是克拉帝尔！是光荣的血盟骑士团成员！","en":"I am Kuradeel! A proud member of Knights of the Blood!","ja":"私はクラディール!栄えある血盟騎士団のメンバーである!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kuradeel_9#originalText","id":"talk.vc.home_wait_kuradeel_9","speaker":{"cn":"克拉帝尔","en":"Kuradeel","ja":"クラディール"},"text":{"cn":"嗯……丝毫没有动静呢。我会继续监视。","en":"Hm...no movement. I will continue to observe.","ja":"ふむ……動きはないようですねこのまま監視を続けます"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kuradeel_10#originalText","id":"talk.vc.home_wait_kuradeel_10","speaker":{"cn":"克拉帝尔","en":"Kuradeel"},"text":{"cn":"你在这里啊？真是的，我稍不注意就这样……","en":"Oh, there you are. I can't turn my back for a minute..."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kureha_1#originalText","id":"talk.vc.home_wait_kureha_1","speaker":{"cn":"红叶","en":"Kureha","ja":"クレハ"},"text":{"cn":"你身边总是异常地围满女孩子呢……真不可思议。","en":"It seems that there's an unusual amount of girls around you... How bizzare.","ja":"あなたの周りって不自然なくらい女の子でいっぱいだよね……不思議"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kureha_2#originalText","id":"talk.vc.home_wait_kureha_2","speaker":{"cn":"红叶","en":"Kureha","ja":"クレハ"},"text":{"cn":"至少要在游戏当中，我一定要变得更强。","en":"I must get stronger in the game.","ja":"ゲームの中でくらいあたしは強くならないといけないんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kureha_3#originalText","id":"talk.vc.home_wait_kureha_3","speaker":{"cn":"红叶","en":"Kureha","ja":"クレハ"},"text":{"cn":"如果有在意的任务就叫上我吧。因为我想变得更加更加强！","en":"I want you to invite me if there are any quests that you are interested in! I want to get even stronger!","ja":"気になるクエストがあったらあたしも誘ってほしいなもっともっと強くなりたいから"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kureha_4#originalText","id":"talk.vc.home_wait_kureha_4","speaker":{"cn":"红叶","en":"Kureha","ja":"クレハ"},"text":{"cn":"悠闲……吗。说起来，最近都没有怎样休息过。","en":"Relax...? Speaking of which, I recently can't take it easy.","ja":"のんびり……かそういえば、最近はあんまりゆっくりしてなかったかも"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kureha_9#originalText","id":"talk.vc.home_wait_kureha_9","speaker":{"cn":"红叶","en":"Kureha","ja":"クレハ"},"text":{"cn":"你还是一样，总是很忙的样子……不过，对受欢迎的你而言是没办法的事吧？","en":"Busy as always... But, you're popular so it can't be helped?","ja":"相変わらず、忙しそうな人……でも、人気者だからしょうがないかな?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_leafa_1#originalText","id":"talk.vc.home_wait_leafa_1","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"我实在不太想看到你躺在床上的模样，像这样在一起比较好。","en":"I'd rather not see you in bed all day. I want to spend time with you like this.","ja":"ベッドで寝ている姿は、あんまり見てたくないんだこうやって一緒にいる方がいい"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_leafa_2#originalText","id":"talk.vc.home_wait_leafa_2","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"这个世界不是游戏，而是趋近现实的幻想。我有这种感觉。","en":"This virtual world is less like a game and more like a realistic fantasy, right? That's the sense I get.","ja":"この世界って、ゲームとは違う現実っぽいファンタジー? そんな感じがする"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_leafa_3#originalText","id":"talk.vc.home_wait_leafa_3","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"假如你以前在现实世界也这么认真练习剑道，明明就会比我还强得多！","en":"If only you'd practiced kendo in the real world as faithfully as you trained in VR. Then you'd be much stronger than me!","ja":"現実世界でもそのくらい真面目に剣道やってたらあたしよりずっと強かったのに! "},"kind":"dialogue"},{"uid":"talk.vc.home_wait_leafa_4#originalText","id":"talk.vc.home_wait_leafa_4","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"我们再一起坐上同一张餐桌，吃妈妈煮的饭吧。说到做到喔！","en":"Promise me we'll eat Mom's cooking together again at the table... Promise me!","ja":"また一緒のテーブルでお母さんのご飯食べようね絶対だよ! "},"kind":"dialogue"},{"uid":"talk.vc.home_wait_leafa_5#originalText","id":"talk.vc.home_wait_leafa_5","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"你没有把我卷进来喔，我是凭着自己的意志来到这里的。","en":"I wasn't roped into this. I came here of my own free will.","ja":"巻き込まれたんじゃないよここには、あたしの意志で来たんだから"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_leafa_6#originalText","id":"talk.vc.home_wait_leafa_6","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"我也想要用《莉法流》的剑术战斗呢。","en":"I'd like to try fighting with my own \"Leafa style.\"","ja":"あたしも《リーファ流》の剣術で戦ってみたいな"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_leafa_7#originalText","id":"talk.vc.home_wait_leafa_7","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"……哥哥，你刚刚在看哪里？？我好像觉得视线飘到胸部来了……","en":"Hey...just where are you looking???","ja":"……ねえお兄ちゃん、今どこ見てる??胸元に視線を感じるんですけど……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_leafa_8#originalText","id":"talk.vc.home_wait_leafa_8","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"我不是说了，我会跟着你到天涯海角吗？所以，我会跟着你喔，直到天涯海角。","en":"Remember? I told you I'd follow you anywhere. So we'll stay together. No matter where you go.","ja":"どこまでも一緒に行くって言ったでしょだから、一緒だよ。どこまでも"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_leafa_9#originalText","id":"talk.vc.home_wait_leafa_9","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"你该不会睡着了吧？呵呵，我帮你盖上毯子喔。","en":"Wait, did you drift off? Hehe, okay, let me tuck you in.","ja":"もしかして、寝ちゃった? ふふ、毛布をかけてあげるね"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_leafa_10#originalText","id":"talk.vc.home_wait_leafa_10","speaker":{"cn":"莉法","en":"Leafa"},"text":{"cn":"辛苦了。欸，要不要和以前一样，稍微比划一下？","en":"Good work today. Hey, wanna relive the good old days and have a little duel?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_leafa_11#originalText","id":"talk.vc.home_wait_leafa_11","speaker":{"cn":"莉法","en":"Leafa"},"text":{"cn":"最近都没见到你，所以我有点担心。不过，还好你看起来过得不错！","en":"I got worried, since I haven't seen you in a while. But I'm glad to see you're doing well!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_leafa_12#originalText","id":"talk.vc.home_wait_leafa_12","speaker":{"cn":"莉法","en":"Leafa"},"text":{"cn":"新年快乐！我带年菜过来啰。","en":"Happy New Year! I brought some New Year's Osechi dishes."},"kind":"dialogue"}]};
